const item = $input.first().json || {};

function decodeBase64Url(input) {
  if (!input || typeof input !== 'string') return '';
  const normalized = input.replace(/-/g, '+').replace(/_/g, '/');
  const pad = normalized.length % 4;
  const padded = pad ? normalized + '='.repeat(4 - pad) : normalized;
  try {
    return Buffer.from(padded, 'base64').toString('utf8');
  } catch {
    return '';
  }
}

function stripHtml(html) {
  if (!html) return '';
  return html
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function collectTextFromPayload(payload) {
  if (!payload) return '';
  if (payload.body && payload.body.data) {
    const mime = (payload.mimeType || '').toLowerCase();
    const text = decodeBase64Url(payload.body.data);
    if (mime.includes('text/plain')) return text;
    if (mime.includes('text/html')) return stripHtml(text);
  }
  if (Array.isArray(payload.parts)) {
    const plainParts = [];
    const htmlParts = [];
    for (const part of payload.parts) {
      const text = collectTextFromPayload(part);
      const mime = (part.mimeType || '').toLowerCase();
      if (!text) continue;
      if (mime.includes('text/plain')) plainParts.push(text);
      else if (mime.includes('text/html')) htmlParts.push(text);
      else plainParts.push(text);
    }
    if (plainParts.length) return plainParts.join('\n');
    if (htmlParts.length) return htmlParts.join('\n');
  }
  return '';
}

function messageToText(msg) {
  const textPlain = msg.textPlain || msg.text || '';
  const textHtml = stripHtml(msg.textHtml || '');
  const payloadText = collectTextFromPayload(msg.payload);
  const snippet = msg.snippet || '';
  return [textPlain, payloadText, textHtml, snippet]
    .map((v) => (typeof v === 'string' ? v.trim() : ''))
    .find((v) => v.length > 0) || '';
}

const content = messageToText(item);
const senderEmail = item.from || item.From || '';
const subject = item.subject || item.Subject || '';

let threadHistory = '';
if (Array.isArray(item.messages) && item.messages.length > 0) {
  threadHistory = item.messages
    .map((m, idx) => {
      const from = m.from || m.From || '';
      const subj = m.subject || m.Subject || '';
      const body = messageToText(m);
      return `Message ${idx + 1}\nFrom: ${from}\nSubject: ${subj}\nBody:\n${body}`;
    })
    .join('\n\n---\n\n')
    .slice(0, 12000);
}

return {
  json: {
    ...item,
    content,
    sender_email: senderEmail,
    subject,
    thread_history: threadHistory,
    knowledge_context: item.knowledge_context || '',
  },
};

