  const lower = body.toLowerCase();
  if (lower.includes('budżet') || lower.includes('lokalizacj') || lower.includes('preferowanych artyst') || lower.includes('termin')) {
    body = 'Dzień dobry,\n\nDziękuję za potwierdzenie dostępności i przesłane informacje. Potwierdzam odbiór i wrócę z dalszymi ustaleniami.\n\nZ poważaniem,\nTomasz Szwecki\nImpresariat Koncertowy';
  }
}
function escapeHtml(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
const draft_body_html = body
  .split(/\n\n+/)
  .map((p) => p.trim())
  .filter(Boolean)
  .map((p) => `<p>${escapeHtml(p)}</p>`)
  .join('');
